# 08_extra_tables.R: census comparison (Q6), trees-vs-stems agreement, informative exceptions
suppressMessages({library(dplyr); library(tidyr)}); options(width = 220); S <- readRDS("out/site_metrics.rds"); rho <- function(a, b) cor(a, b, method = "spearman", use = "complete.obs")
a <- S[S$set == "1985_tree", ]; b <- S[S$set == "2015_tree", ]; stopifnot(identical(a$quad, b$quad)); a$swamp <- a$habitat == "swamp"
ch <- data.frame(quad = a$quad, habitat = a$habitat, dLCBD = b$LCBD_hel - a$LCBD_hel, dLCBD_occ = b$LCBD_hel_occ - a$LCBD_hel_occ, dT_rel = b$T_rel - a$T_rel, dT_occ = b$T_occ - a$T_occ, dTplus_rel = b$T_plus_rel - a$T_plus_rel, d_rich = b$richness - a$richness, d_indiv = b$individuals - a$individuals,
  pct_LCBD85 = rank(a$LCBD_hel) / 1250, pct_LCBD15 = rank(b$LCBD_hel) / 1250, pct_Tocc85 = rank(a$T_occ) / 1250, pct_Tocc15 = rank(b$T_occ) / 1250, pct_Trel85 = rank(a$T_rel) / 1250, pct_Trel15 = rank(b$T_rel) / 1250)
write.csv(ch, "tables/q6_quadrat_changes.csv", row.names = FALSE)
hc <- ch |> group_by(habitat) |> summarise(n = n(), median_dLCBD_e3 = 1e3 * median(dLCBD), median_dLCBD_occ_e3 = 1e3 * median(dLCBD_occ), median_dT_rel = median(dT_rel), median_dT_occ = median(dT_occ), median_dTplus_rel = median(dTplus_rel), median_d_rich = median(d_rich), median_d_indiv = median(d_indiv), mean_pct_LCBD85 = mean(pct_LCBD85), mean_pct_LCBD15 = mean(pct_LCBD15), mean_pct_Tocc85 = mean(pct_Tocc85), mean_pct_Tocc15 = mean(pct_Tocc15), mean_pct_Trel85 = mean(pct_Trel85), mean_pct_Trel15 = mean(pct_Trel15), .groups = "drop"); write.csv(hc, "tables/q6_habitat_changes.csv", row.names = FALSE); print(hc |> mutate(across(where(is.numeric), ~ round(., 3))))
cat("\ninter-census Spearman (quadrat level): LCBD", round(rho(a$LCBD_hel, b$LCBD_hel), 2), " LCBD_occ", round(rho(a$LCBD_hel_occ, b$LCBD_hel_occ), 2), " T_rel", round(rho(a$T_rel, b$T_rel), 2), " T_occ", round(rho(a$T_occ, b$T_occ), 2), " T+_rel", round(rho(a$T_plus_rel, b$T_plus_rel), 2), " LCZD_rel_20", round(rho(a$LCZD_rel_20, b$LCZD_rel_20), 2), " LCZD_inc_20", round(rho(a$LCZD_inc_20, b$LCZD_inc_20), 2), "\n")
cat("swamp-only inter-census Spearman: LCBD", round(rho(a$LCBD_hel[a$swamp], b$LCBD_hel[a$swamp]), 2), " LCBD_occ", round(rho(a$LCBD_hel_occ[a$swamp], b$LCBD_hel_occ[a$swamp]), 2), " T_rel", round(rho(a$T_rel[a$swamp], b$T_rel[a$swamp]), 2), " T_occ", round(rho(a$T_occ[a$swamp], b$T_occ[a$swamp]), 2), "\n")
# swamp vs rest, pooled change in the abundance retention (LCBD, T_rel)
cat("\nswamp mean LCBD (e-3):", round(1e3 * mean(a$LCBD_hel[a$swamp]), 3), "->", round(1e3 * mean(b$LCBD_hel[a$swamp]), 3), "; others", round(1e3 * mean(a$LCBD_hel[!a$swamp]), 3), "->", round(1e3 * mean(b$LCBD_hel[!a$swamp]), 3), "\n")
cat("swamp mean LCBD_occ (e-3):", round(1e3 * mean(a$LCBD_hel_occ[a$swamp]), 3), "->", round(1e3 * mean(b$LCBD_hel_occ[a$swamp]), 3), "; others", round(1e3 * mean(a$LCBD_hel_occ[!a$swamp]), 3), "->", round(1e3 * mean(b$LCBD_hel_occ[!a$swamp]), 3), "\n")
cat("swamp quadrats in the top 5% LCBD_occ:", sum(rank(-a$LCBD_hel_occ)[a$swamp] <= 63), "(1985)", sum(rank(-b$LCBD_hel_occ)[a$swamp] <= 63), "(2015) of 63\n")
cat("swamp quadrats in the top 5% LCBD:", sum(rank(-a$LCBD_hel)[a$swamp] <= 63), "(1985)", sum(rank(-b$LCBD_hel)[a$swamp] <= 63), "(2015) of 63\n")
# ---- trees vs stems
for (y in c("1985", "2015")) { t <- S[S$set == paste0(y, "_tree"), ]; s <- S[S$set == paste0(y, "_stem"), ]; cat(y, "tree vs stem Spearman: LCBD", round(rho(t$LCBD_hel, s$LCBD_hel), 3), "T_rel", round(rho(t$T_rel, s$T_rel), 3), "T_occ", round(rho(t$T_occ, s$T_occ), 3), "; swamp LCBD pct tree/stem", round(mean(rank(t$LCBD_hel)[t$habitat == "swamp"] / 1250), 3), round(mean(rank(s$LCBD_hel)[s$habitat == "swamp"] / 1250), 3), "\n") }
# ---- informative exceptions (1985), occurrence representation
a$pLCBDo <- rank(a$LCBD_hel_occ) / 1250; exo <- a |> filter(pLCBDo >= .95) |> arrange(desc(T_occ)) |> transmute(quad, habitat, LCBD_occ = LCBD_hel_occ, T_occ, T_plus_occ, individuals, richness, pLCBDo, pTocc = rank(a$T_occ)[match(quad, a$quad)] / 1250); write.csv(exo, "tables/exceptions_top5pct_LCBD_occ.csv", row.names = FALSE); cat("\nTop-5% LCBD_occ: n", nrow(exo), "habitats\n"); print(table(exo$habitat)); cat("T_occ percentile among them: median", round(median(exo$pTocc), 2), " share > median:", round(mean(exo$pTocc > .5), 2), " swamp share > median:", round(mean(exo$pTocc[exo$habitat == "swamp"] > .5), 2), "\nlowest-T_occ distinct (pTocc<0.1):\n"); print(exo[exo$pTocc < .1, ])
# ---- informative exceptions (1985), abundance
a$pLCBD <- rank(a$LCBD_hel) / 1250; a$pTocc <- rank(a$T_occ) / 1250; a$pTrel <- rank(a$T_rel) / 1250; a$pTplus <- rank(a$T_plus_rel) / 1250
ex <- a |> filter(pLCBD >= .95) |> arrange(desc(T_occ)) |> select(quad, habitat, LCBD_hel, T_rel, T_plus_rel, T_occ, individuals, richness, pLCBD, pTocc, pTrel); write.csv(ex, "tables/exceptions_top5pct_LCBD.csv", row.names = FALSE)
cat("\nTop-5% LCBD quadrats (n=", nrow(ex), "): habitat counts\n"); print(table(ex$habitat)); cat("share with T_occ above regional median:", round(mean(ex$pTocc > .5), 2), "; above 75th pct:", round(mean(ex$pTocc > .75), 2), "\n")
cat("non-swamp among top 5%:\n"); print(ex |> filter(habitat != "swamp") |> mutate(across(where(is.numeric), ~ round(., 4))))
cat("\nlow LCBD but low T_occ (LCBD<median, T_occ bottom 10%):", sum(a$pLCBD < .5 & a$pTocc <= .1), " of ", sum(a$pTocc <= .1), "\n")
